using System.ComponentModel.DataAnnotations;

namespace RecipeHub.Models;

public class Recipe
{
    public int Id { get; set; }

    [Required, StringLength(100)]
    public string Title { get; set; } = string.Empty;

    public string Category { get; set; } = string.Empty;

    [Required, MinLength(1)]
    public List<string> Ingredients { get; set; } = [];

    [Required, MinLength(1)]
    public List<string> Steps { get; set; } = [];

    public double AverageRating { get; set; }
    public int RatingCount { get; set; }
}

public static class RecipeStore
{
    private static readonly List<Recipe> _recipes =
    [
        new()
        {
            Id = 1, Title = "Classic Pancakes", Category = "Breakfast",
            Ingredients = ["2 cups flour", "2 eggs", "1.5 cups milk", "2 tbsp sugar", "1 tsp baking powder"],
            Steps = ["Mix dry ingredients.", "Whisk eggs and milk together.", "Combine wet and dry.", "Cook on griddle until golden."],
            AverageRating = 4.5, RatingCount = 12
        },
        new()
        {
            Id = 2, Title = "Spaghetti Bolognese", Category = "Dinner",
            Ingredients = ["400g spaghetti", "500g ground beef", "1 can crushed tomatoes", "1 onion", "2 cloves garlic"],
            Steps = ["Cook pasta al dente.", "Sauté onion and garlic.", "Brown the beef.", "Add tomatoes, simmer 20 min.", "Serve sauce over pasta."],
            AverageRating = 4.8, RatingCount = 24
        },
        new()
        {
            Id = 3, Title = "Caesar Salad", Category = "Lunch",
            Ingredients = ["1 romaine lettuce", "Croutons", "Parmesan cheese", "Caesar dressing", "Grilled chicken"],
            Steps = ["Chop lettuce.", "Toss with dressing.", "Top with croutons, cheese, and chicken."],
            AverageRating = 4.2, RatingCount = 8
        },
        new()
        {
            Id = 4, Title = "Chocolate Chip Cookies", Category = "Desserts",
            Ingredients = ["2.25 cups flour", "1 cup butter", "0.75 cup sugar", "2 eggs", "2 cups chocolate chips"],
            Steps = ["Cream butter and sugar.", "Beat in eggs.", "Mix in flour.", "Fold in chocolate chips.", "Bake at 375°F for 10 min."],
            AverageRating = 4.9, RatingCount = 30
        },
        new()
        {
            Id = 5, Title = "Avocado Toast", Category = "Breakfast",
            Ingredients = ["2 slices sourdough", "1 avocado", "Salt and pepper", "Red pepper flakes", "Lemon juice"],
            Steps = ["Toast bread.", "Mash avocado with lemon, salt, pepper.", "Spread on toast.", "Sprinkle red pepper flakes."],
            AverageRating = 4.0, RatingCount = 6
        },
        new()
        {
            Id = 6, Title = "Grilled Chicken Tacos", Category = "Dinner",
            Ingredients = ["4 chicken thighs", "Taco shells", "Salsa", "Sour cream", "Shredded lettuce"],
            Steps = ["Season and grill chicken.", "Slice into strips.", "Assemble tacos with toppings."],
            AverageRating = 4.6, RatingCount = 15
        }
    ];

    public static IReadOnlyList<Recipe> All => _recipes;

    public static IEnumerable<string> Categories =>
        _recipes.Select(r => r.Category).Distinct().OrderBy(c => c);

    public static IEnumerable<Recipe> ByCategory(string category) =>
        _recipes.Where(r => r.Category.Equals(category, StringComparison.OrdinalIgnoreCase));

    public static Recipe? GetById(int id) => _recipes.FirstOrDefault(r => r.Id == id);

    public static void Add(Recipe recipe)
    {
        recipe.Id = _recipes.Max(r => r.Id) + 1;
        _recipes.Add(recipe);
    }

    public static void Rate(int recipeId, int stars)
    {
        var recipe = GetById(recipeId);
        if (recipe is null) return;
        var totalStars = recipe.AverageRating * recipe.RatingCount + stars;
        recipe.RatingCount++;
        recipe.AverageRating = totalStars / recipe.RatingCount;
    }
}

@page "/category/{CategoryName}"
@using RecipeHub.Models

<PageTitle>@CategoryName Recipes - RecipeHub</PageTitle>

<div class="container py-4">
    <nav aria-label="breadcrumb">
        <ol class="breadcrumb">
            <li class="breadcrumb-item"><a href="/">Home</a></li>
            <li class="breadcrumb-item active">@CategoryName</li>
        </ol>
    </nav>

    <h1>@CategoryName Recipes</h1>

    @if (!recipes.Any())
    {
        <div class="alert alert-info">No recipes found in this category.</div>
    }
    else
    {
        <div class="row g-4">
            @foreach (var recipe in recipes)
            {
                <div class="col-md-6">
                    <div class="card h-100 shadow-sm">
                        <div class="card-body">
                            <h5 class="card-title">@recipe.Title</h5>
                            <p class="text-warning mb-1">
                                @for (int i = 1; i <= 5; i++)
                                {
                                    <span>@(i <= (int)Math.Round(recipe.AverageRating) ? "★" : "☆")</span>
                                }
                                <small class="text-muted ms-1">(@recipe.AverageRating.ToString("F1")) · @recipe.RatingCount ratings</small>
                            </p>
                            <a href="/recipe/@recipe.Id" class="btn btn-sm btn-outline-primary mt-2">View Recipe</a>
                        </div>
                    </div>
                </div>
            }
        </div>
    }
</div>

@code {
    [Parameter] public string CategoryName { get; set; } = string.Empty;

    private IEnumerable<Recipe> recipes => RecipeStore.ByCategory(CategoryName);
}

@page "/recipe/{Id:int}"
@using RecipeHub.Models

<PageTitle>@(recipe?.Title ?? "Recipe") - RecipeHub</PageTitle>

<div class="container py-4">
    <nav aria-label="breadcrumb">
        <ol class="breadcrumb">
            <li class="breadcrumb-item"><a href="/">Home</a></li>
            @if (recipe is not null)
            {
                <li class="breadcrumb-item"><a href="/category/@recipe.Category">@recipe.Category</a></li>
                <li class="breadcrumb-item active">@recipe.Title</li>
            }
        </ol>
    </nav>

    @if (recipe is null)
    {
        <div class="alert alert-warning">Recipe not found.</div>
    }
    else
    {
        <h1>@recipe.Title</h1>
        <p class="text-muted">Category: @recipe.Category · @recipe.RatingCount ratings</p>

        <StarRating RecipeId="recipe.Id" @rendermode="InteractiveServer" />

        <h3 class="mt-4">Ingredients</h3>
        <ul class="list-group list-group-flush mb-4">
            @foreach (var ingredient in recipe.Ingredients)
            {
                <li class="list-group-item">@ingredient</li>
            }
        </ul>

        <h3>Steps</h3>
        <ol class="list-group list-group-numbered mb-4">
            @foreach (var step in recipe.Steps)
            {
                <li class="list-group-item">@step</li>
            }
        </ol>
    }
</div>

@code {
    [Parameter] public int Id { get; set; }

    private Recipe? recipe;

    protected override void OnInitialized()
    {
        recipe = RecipeStore.GetById(Id);
    }
}

@page "/submit"
@using RecipeHub.Models
@rendermode InteractiveServer

<PageTitle>Submit a Recipe - RecipeHub</PageTitle>

<div class="container py-4">
    <nav aria-label="breadcrumb">
        <ol class="breadcrumb">
            <li class="breadcrumb-item"><a href="/">Home</a></li>
            <li class="breadcrumb-item active">Submit Recipe</li>
        </ol>
    </nav>

    <h1>📝 Submit a Recipe</h1>

    @if (submitted)
    {
        <div class="alert alert-success">
            <strong>Thank you!</strong> Your recipe "<strong>@model.Title</strong>" has been submitted.
            <a href="/recipe/@submittedId">View it here</a>.
        </div>
    }
    else
    {
        <EditForm Model="model" OnValidSubmit="HandleSubmit" FormName="submit-recipe">
            <DataAnnotationsValidator />
            <ValidationSummary class="text-danger" />

            <div class="mb-3">
                <label class="form-label">Recipe Title</label>
                <InputText @bind-Value="model.Title" class="form-control" placeholder="e.g., Grandma's Apple Pie" />
                <ValidationMessage For="() => model.Title" class="text-danger" />
            </div>

            <div class="mb-3">
                <label class="form-label">Category</label>
                <InputSelect @bind-Value="model.Category" class="form-select">
                    <option value="">-- Select a category --</option>
                    <option value="Breakfast">Breakfast</option>
                    <option value="Lunch">Lunch</option>
                    <option value="Dinner">Dinner</option>
                    <option value="Desserts">Desserts</option>
                </InputSelect>
                <ValidationMessage For="() => model.Category" class="text-danger" />
            </div>

            <div class="mb-3">
                <label class="form-label">Ingredients (one per line)</label>
                <InputTextArea @bind-Value="ingredientsText" class="form-control" rows="5"
                    placeholder="2 cups flour&#10;1 cup sugar&#10;3 eggs" />
            </div>

            <div class="mb-3">
                <label class="form-label">Steps (one per line)</label>
                <InputTextArea @bind-Value="stepsText" class="form-control" rows="5"
                    placeholder="Preheat oven to 350°F&#10;Mix ingredients&#10;Bake for 30 minutes" />
            </div>

            <button type="submit" class="btn btn-success">Submit Recipe</button>
        </EditForm>
    }
</div>

@code {
    private RecipeFormModel model = new();
    private string ingredientsText = string.Empty;
    private string stepsText = string.Empty;
    private bool submitted;
    private int submittedId;

    private void HandleSubmit()
    {
        var recipe = new Recipe
        {
            Title = model.Title,
            Category = model.Category,
            Ingredients = ingredientsText.Split('\n', StringSplitOptions.RemoveEmptyEntries | StringSplitOptions.TrimEntries).ToList(),
            Steps = stepsText.Split('\n', StringSplitOptions.RemoveEmptyEntries | StringSplitOptions.TrimEntries).ToList()
        };

        RecipeStore.Add(recipe);
        submittedId = recipe.Id;
        submitted = true;
    }

    private class RecipeFormModel
    {
        [Required(ErrorMessage = "Title is required.")]
        [StringLength(100)]
        public string Title { get; set; } = string.Empty;

        [Required(ErrorMessage = "Please select a category.")]
        public string Category { get; set; } = string.Empty;
    }
}

@using RecipeHub.Models

<div class="my-3">
    <span class="fs-5">Rate this recipe: </span>
    @for (int i = 1; i <= 5; i++)
    {
        var star = i;
        <button class="btn btn-link fs-4 p-0 text-decoration-none"
                @onclick="() => SubmitRating(star)"
                title="Rate @star stars"
                disabled="@hasRated">
            <span class="@(star <= displayRating ? "text-warning" : "text-secondary")">
                @(star <= displayRating ? "★" : "☆")
            </span>
        </button>
    }
    @if (hasRated)
    {
        <span class="ms-2 text-success">✓ Thanks for rating!</span>
    }
</div>

@code {
    [Parameter, EditorRequired]
    public int RecipeId { get; set; }

    private int displayRating;
    private bool hasRated;

    protected override void OnInitialized()
    {
        var recipe = RecipeStore.GetById(RecipeId);
        displayRating = recipe is not null ? (int)Math.Round(recipe.AverageRating) : 0;
    }

    private void SubmitRating(int stars)
    {
        if (hasRated) return;
        RecipeStore.Rate(RecipeId, stars);
        displayRating = stars;
        hasRated = true;
    }
}

